def find_max_palindromic_cube(N: int) -> int:
    max_palindromic_cube = 0
    x = 1
    while True:
        cube = x ** 3
        if cube > N:
            break
        cube_str = str(cube)
        if cube_str == cube_str[::-1]:
            if cube > max_palindromic_cube:
                max_palindromic_cube = cube
        x += 1
    return max_palindromic_cube
